  );
}

'use client';
import { useState } from 'react';
import { useRouter, useSearchParams } from 'next/navigation';
import Link from 'next/link';
import { Loader2, Eye, EyeOff } from 'lucide-react';
import { resetPassword } from '@/lib/actions/password';

export default function ResetPasswordClient() {
  const router = useRouter();
  const searchParams = useSearchParams();
  const token = searchParams.get('token');

  const [password, setPassword] = useState('');
  const [showPw, setShowPw]     = useState(false);
  const [loading, setLoading]   = useState(false);
  const [success, setSuccess]   = useState(false);
  const [error, setError]       = useState('');

  async function handleSubmit(e: React.FormEvent) {
    e.preventDefault();
    if (!token) {
      setError('Missing reset token. Please request a new password reset link.');
      return;
    }
    
    setLoading(true);
    setError('');
    
    try {
      const result = await resetPassword(token, password);
      if (!result.success) {
        setError(result.error || 'Failed to reset password');
        setLoading(false);
        return;
      }
      setSuccess(true);
      setTimeout(() => {
        router.push('/login');
      }, 3000);
    } catch (err: any) {
      setError(err.message || 'Failed to reset password. The token may be expired.');
    } finally {
      setLoading(false);
    }
  }

  if (!token) {
    return (
      <div style={{ minHeight: '100vh', display: 'flex', alignItems: 'center', justifyContent: 'center', background: 'var(--bg-app)', padding: '1.5rem' }}>
        <div className="card animate-in" style={{ width: '100%', maxWidth: 400, padding: '2rem', textAlign: 'center' }}>
          <div style={{ padding: '1rem', background: 'var(--color-expense-light)', borderRadius: 8, color: 'var(--color-expense)' }}>
            <p style={{ fontWeight: 600 }}>Invalid Reset Link</p>
            <p style={{ fontSize: '0.8rem', marginTop: '0.5rem' }}>The password reset link is missing a token.</p>
          </div>
          <Link href="/forgot-password" style={{ display: 'inline-block', marginTop: '1.5rem', color: 'var(--color-brand)', fontWeight: 500, fontSize: '0.875rem' }}>
            Request new link
          </Link>
        </div>
      </div>
    );
  }

  return (
    <div style={{ minHeight: '100vh', display: 'flex', alignItems: 'center', justifyContent: 'center', background: 'var(--bg-app)', padding: '1.5rem' }}>
      <div className="card animate-in" style={{ width: '100%', maxWidth: 400, padding: '2rem', boxShadow: '0 20px 60px rgba(0,0,0,0.12)' }}>
        <div style={{ textAlign: 'center', marginBottom: '2rem' }}>
          <h1 style={{ fontSize: '1.5rem', fontWeight: 800, marginBottom: '0.5rem', color: 'var(--color-text-primary)' }}>New Password</h1>
          <p style={{ fontSize: '0.875rem', color: 'var(--color-text-secondary)' }}>Enter your new password below</p>
        </div>

        {error && (
          <div style={{ padding: '0.75rem 1rem', borderRadius: 8, background: 'var(--color-expense-light)', color: 'var(--color-expense)', fontSize: '0.8125rem', marginBottom: '1rem', fontWeight: 500 }}>
            {error}
          </div>
        )}

        {success ? (
          <div style={{ textAlign: 'center', padding: '1rem', background: 'var(--color-income-light)', borderRadius: 8 }}>
            <p style={{ color: 'var(--color-income)', fontWeight: 600, fontSize: '0.875rem' }}>Password reset successful!</p>
            <p style={{ color: 'var(--color-text-secondary)', fontSize: '0.78rem', marginTop: '0.5rem' }}>Redirecting to login...</p>
          </div>
        ) : (
          <form onSubmit={handleSubmit} style={{ display: 'flex', flexDirection: 'column', gap: '1rem' }}>
            <div>
              <label style={{ display: 'block', fontSize: '0.78rem', fontWeight: 600, color: 'var(--color-text-secondary)', marginBottom: '0.4rem' }}>
                New Password <span style={{ color: 'var(--color-text-secondary)', fontWeight: 400 }}>(min 8 chars)</span>
              </label>
              <div style={{ position: 'relative' }}>
                <input 
                  type={showPw ? 'text' : 'password'} 
                  value={password} 
                  onChange={e => setPassword(e.target.value)} 
                  required 
                  minLength={8} 
                  placeholder="••••••••"
                  className="input-field" 
                  style={{ width: '100%', padding: '0.625rem 2.5rem 0.625rem 0.875rem', fontSize: '0.875rem' }} 
                />
                <button type="button" onClick={() => setShowPw(v => !v)} style={{ position: 'absolute', right: '0.75rem', top: '50%', transform: 'translateY(-50%)', background: 'none', border: 'none', cursor: 'pointer', color: 'var(--color-text-secondary)', display: 'flex' }}>
                  {showPw ? <EyeOff size={15} /> : <Eye size={15} />}
                </button>
              </div>
              {password.length > 0 && (
                <div style={{ marginTop: '0.4rem', display: 'flex', gap: '0.25rem' }}>
                  {[...Array(4)].map((_, i) => (
                    <div key={i} style={{ flex: 1, height: 3, borderRadius: 2, background: password.length >= (i + 1) * 3 ? (password.length >= 12 ? 'var(--color-income)' : 'var(--warning)') : 'var(--border)', transition: 'background 0.2s' }} />
                  ))}
                </div>
              )}
            </div>
            
            <button type="submit" disabled={loading} className="btn btn-primary" style={{ width: '100%', padding: '0.75rem', fontSize: '0.9rem', justifyContent: 'center' }}>
              {loading ? <Loader2 size={16} style={{ animation: 'spin 1s linear infinite' }} /> : 'Reset Password'}
            </button>
          </form>
        )}
      </div>
    </div>
  );
}

'use client';
// src/components/DashboardCharts.tsx
// Accepts live chartData prop from Server Component — no internal mock data.
import {
  AreaChart, Area, XAxis, YAxis,
  CartesianGrid, Tooltip, ResponsiveContainer, Legend,
  PieChart, Pie, Cell,
} from 'recharts';
import { fmtAdaptive, fmtCompact } from '@/lib/format';
import { useRouter } from 'next/navigation';

export type ChartMonthPoint = {
  month: string;
  income: number;
  expenses: number;
};

export type DonutPoint = {
  name: string;
  value: number;
  pct: number;
};

/* -- Shared chart colours ----------------------------------- */
const DONUT_COLORS = [
  'var(--chart-1)', 'var(--chart-2)', 'var(--chart-3)', 'var(--chart-4)',
  'var(--chart-5)', 'var(--chart-6)', 'var(--chart-income)', 'var(--chart-savings)'
];

/* -- Tooltip components ------------------------------------- */
function FlowTip({ active, payload, label, currency }: any) {
  if (!active || !payload?.length) return null;
  return (
    <div style={{ background: 'var(--surface-card)', border: '1px solid var(--border)', borderRadius: 8, padding: '0.625rem 0.875rem', boxShadow: 'var(--shadow-md)' }}>
      <p style={{ fontSize: '0.7rem', fontWeight: 700, textTransform: 'uppercase', letterSpacing: '0.06em', color: 'var(--color-text-secondary)', marginBottom: '0.35rem' }}>{label}</p>
      {payload.map((p: any) => (
        <div key={p.name} style={{ display: 'flex', alignItems: 'center', gap: '0.4rem', marginBottom: '0.1rem' }}>
          <div style={{ width: 8, height: 8, borderRadius: '50%', background: p.color, flexShrink: 0 }} />
          <span style={{ fontSize: '0.8rem', color: 'var(--color-text-secondary)' }}>{p.name}:</span>
          <span style={{ fontSize: '0.8rem', fontWeight: 700, fontFamily: 'Space Grotesk, sans-serif' }}>
            {fmtAdaptive(p.value, currency)}
          </span>
        </div>
      ))}
    </div>
  );
}

function PieTip({ active, payload, total, currency }: any) {
  if (!active || !payload?.length) return null;
  return (
    <div style={{ background: 'var(--surface-card)', border: '1px solid var(--border)', borderRadius: 8, padding: '0.625rem 0.875rem', boxShadow: 'var(--shadow-md)' }}>
      <p style={{ fontSize: '0.8rem', fontWeight: 700, color: 'var(--color-text-primary)' }}>{payload[0].name}</p>
      <p style={{ fontSize: '0.8rem', fontWeight: 700, fontFamily: 'Space Grotesk, sans-serif', color: 'var(--color-text-primary)' }}>{fmtAdaptive(payload[0].value, currency)}</p>
      {total > 0 && <p style={{ fontSize: '0.7rem', color: 'var(--color-text-secondary)' }}>{((payload[0].value / total) * 100).toFixed(1)}% of spending</p>}
    </div>
  );
}

const tick = { fontSize: 10, fill: 'var(--color-text-secondary)', fontFamily: 'Inter, sans-serif' };

const RADIAN = Math.PI / 180;
function PieLabel({ cx, cy, midAngle, innerRadius, outerRadius, percent }: any) {
  if (percent < 0.08) return null;
  const r = innerRadius + (outerRadius - innerRadius) * 0.55;
  return (
    <text x={cx + r * Math.cos(-midAngle * RADIAN)} y={cy + r * Math.sin(-midAngle * RADIAN)}
      fill="white" textAnchor="middle" dominantBaseline="central"
      style={{ fontSize: '0.62rem', fontWeight: 700 }}>
      {`${(percent * 100).toFixed(0)}%`}
    </text>
  );
}

export function EmptyChartState({ title }: { title: string }) {
  return (
    <div style={{ textAlign: 'center', padding: '2.5rem 1rem', color: 'var(--color-text-secondary)', background: 'var(--surface-card)', borderRadius: 12, border: '1px dashed var(--border)', display: 'flex', flexDirection: 'column', alignItems: 'center', justifyContent: 'center', height: '100%' }}>
      <div style={{ fontSize: '2rem', marginBottom: '0.75rem', opacity: 0.5 }}>📊</div>
      <div style={{ fontSize: '0.85rem', fontWeight: 600, color: 'var(--color-text-primary)' }}>No data to display</div>
      <div style={{ fontSize: '0.75rem', marginTop: '0.25rem' }}>{title}</div>
    </div>
  );
}

/* -- Cash Flow Area Chart ----------------------------------- */
export function CashFlowChart({ data, currency = 'KES' }: { data: ChartMonthPoint[], currency?: string }) {
  const router = useRouter();
  
  const hasData = data.some(d => d.income > 0 || d.expenses > 0);
  if (!hasData) {
    return <div style={{ height: 210 }}><EmptyChartState title="Record some income or expenses to see your cash flow trend." /></div>;
  }

  const chartData = data.map(d => ({
    label:    d.month,
    Income:   d.income,
    Expenses: d.expenses,
  }));

  return (
    <ResponsiveContainer width="100%" height={210}>
      <AreaChart data={chartData} margin={{ top: 4, right: 4, left: -28, bottom: 0 }} onClick={(e) => {
        if (e && e.activeLabel) {
           router.push(`/transactions?search=${encodeURIComponent(e.activeLabel)}`);
        }
      }} style={{ cursor: 'pointer' }}>
        <defs>
          <linearGradient id="gIncome"  x1="0" y1="0" x2="0" y2="1">
            <stop offset="0%"   stopColor="var(--chart-income)"  stopOpacity={0.22}/>
            <stop offset="100%" stopColor="var(--chart-income)"  stopOpacity={0}/>
          </linearGradient>
          <linearGradient id="gExpense" x1="0" y1="0" x2="0" y2="1">
            <stop offset="0%"   stopColor="var(--chart-expense)" stopOpacity={0.18}/>
            <stop offset="100%" stopColor="var(--chart-expense)" stopOpacity={0}/>
          </linearGradient>
        </defs>
        <CartesianGrid strokeDasharray="3 3" vertical={false} stroke="var(--border)" />
        <XAxis dataKey="label" tick={tick} tickLine={false} axisLine={false} dy={6} />
        <YAxis tick={tick} tickLine={false} axisLine={false} tickFormatter={v => fmtCompact(v, currency)} />
        <Tooltip content={<FlowTip currency={currency} />} />
        <Legend iconType="circle" iconSize={7} wrapperStyle={{ fontSize: '0.75rem', paddingTop: 8 }} />
        <Area name="Income"   dataKey="Income"   type="monotone" stroke="var(--chart-income)"  strokeWidth={2.5} fill="url(#gIncome)"  activeDot={{ r: 4, strokeWidth: 0 }} />
        <Area name="Expenses" dataKey="Expenses" type="monotone" stroke="var(--chart-expense)" strokeWidth={2.5} fill="url(#gExpense)" activeDot={{ r: 4, strokeWidth: 0 }} />
      </AreaChart>
    </ResponsiveContainer>
  );
}

/* -- Spending Donut Chart ----------------------------------- */
export function SpendingDonutChart({ data, currency = 'KES' }: { data: DonutPoint[], currency?: string }) {
  const router = useRouter();
  const total = data.reduce((s, d) => s + d.value, 0);

  // Fallback empty state
  if (data.length === 0 || total === 0) {
    return (
      <div style={{ height: 210 }}>
        <EmptyChartState title="Record some expenses to see your spending breakdown." />
      </div>
    );
  }

  const colored = data.map((d, i) => ({ ...d, color: DONUT_COLORS[i % DONUT_COLORS.length] }));

  return (
    <div style={{ display: 'flex', flexDirection: 'column', gap: '0.75rem', minWidth: 0 }}>
      <div style={{ overflow: 'visible' }}>
        <ResponsiveContainer width="100%" height={170}>
          <PieChart>
            <Pie data={colored} cx="50%" cy="50%" innerRadius={44} outerRadius={74}
              paddingAngle={2} dataKey="value" stroke="none" labelLine={false} label={<PieLabel />}
              onClick={(e) => {
                if (e && e.name) router.push(`/transactions?search=${encodeURIComponent(e.name)}`);
              }}
              style={{ cursor: 'pointer' }}
            >
              {colored.map((d, i) => <Cell key={i} fill={d.color} />)}
            </Pie>
            <Tooltip content={<PieTip total={total} currency={currency} />} />
          </PieChart>
        </ResponsiveContainer>
      </div>
      <div style={{ display: 'grid', gridTemplateColumns: '1fr 1fr', gap: '0.3rem 0.75rem' }}>
        {colored.map(d => (
          <div key={d.name} style={{ display: 'flex', alignItems: 'center', gap: '0.35rem', minWidth: 0 }}>
            <div style={{ width: 7, height: 7, borderRadius: '50%', background: d.color, flexShrink: 0, boxShadow: `0 0 5px ${d.color}99` }} />
            <span style={{ fontSize: '0.68rem', color: 'var(--color-text-secondary)', flex: 1, overflow: 'hidden', textOverflow: 'ellipsis', whiteSpace: 'nowrap' }}>{d.name}</span>
            <span style={{ fontSize: '0.68rem', fontWeight: 700, color: 'var(--color-text-primary)', fontFamily: 'Space Grotesk, sans-serif', flexShrink: 0 }}>
              {d.pct}%
            </span>
          </div>
        ))}
      </div>
    </div>
  );
}

'use client';
// src/components/MpesaSmsInput.tsx
// Paste M-Pesa SMS messages → Gemini parses → shows transactions for import
// Copyright (c) 2024-present Eric Gitahi. All rights reserved.
import { useState } from 'react';
import { Smartphone, Loader2, CheckCircle2, AlertCircle, ChevronRight, X } from 'lucide-react';

interface ParsedTx {
  name: string; date: string; amount: number;
  type: 'income' | 'expense'; category: string; fee?: number; ref?: string;
}

interface Props {
  onImport: (txs: ParsedTx[]) => void;
}

const EXAMPLE_SMS = `FG7K2X8L Confirmed. KES1,500 sent to JOHN KAMAU 0722XXXXXX on 27/5/25 at 3:14 PM. New M-PESA balance is KES 8,432. Transaction cost KES 27.

QK3P9XY2 Confirmed. You have received KES5,000 from JANE WANJIKU 0733XXXXXX on 27/5/25 at 9:02 AM. New M-PESA balance is KES 13,432.

RN5M4HJ1 Confirmed. KES2,000 paid to KPLC(paybill number 888880) on 26/5/25 at 7:45 PM. New M-PESA balance is KES 11,432. Transaction cost KES 33.`;

export function MpesaSmsInput({ onImport }: Props) {
  const [sms,       setSms]       = useState('');
  const [state,     setState]     = useState<'idle' | 'parsing' | 'review' | 'error'>('idle');
  const [parsed,    setParsed]    = useState<ParsedTx[]>([]);
  const [selected,  setSelected]  = useState<Set<number>>(new Set());
  const [errMsg,    setErrMsg]    = useState('');

  async function handleParse() {
    if (!sms.trim()) return;
    setState('parsing');
    try {
      const formData = new FormData();
      formData.append('text', sms);

      const res = await fetch('/api/upload', {
        method: 'POST',
        body: formData,
      });
      const data = await res.json();
      if (!res.ok) throw new Error(data.error ?? 'Parse failed');
      if (!data.transactions?.length) throw new Error('No transactions found in that SMS text');
      setParsed(data.transactions);
      setSelected(new Set(data.transactions.map((_: any, i: number) => i)));
      setState('review');
    } catch (e: any) {
      setErrMsg(e.message);
      setState('error');
    }
  }

  function handleImport() {
    const toImport = parsed.filter((_, i) => selected.has(i));
    onImport(toImport);
    setSms(''); setParsed([]); setSelected(new Set()); setState('idle');
  }

  function toggleRow(i: number) {
    setSelected(prev => {
      const next = new Set(prev);
      if (next.has(i)) {
        next.delete(i);
      } else {
        next.add(i);
      }
      return next;
    });
  }

  if (state === 'parsing') return (
    <div style={{ textAlign: 'center', padding: '2rem' }}>
      <Loader2 size={36} color="var(--color-brand)" style={{ margin: '0 auto 1rem', animation: 'spin 1s linear infinite' }} />
      <div style={{ fontWeight: 700, fontSize: '0.9rem', color: 'var(--color-text-primary)', marginBottom: '0.25rem' }}>
        Gemini AI is reading your SMS…
      </div>
      <p style={{ fontSize: '0.75rem', color: 'var(--color-text-secondary)' }}>Extracting and categorising M-Pesa transactions</p>
    </div>
  );

  if (state === 'review') return (
    <div>
      <div style={{ display: 'flex', alignItems: 'center', justifyContent: 'space-between', marginBottom: '0.875rem', flexWrap: 'wrap', gap: '0.5rem' }}>
        <div>
          <div style={{ fontWeight: 700, fontSize: '0.9rem', color: 'var(--color-text-primary)' }}>
            {parsed.length} transaction{parsed.length !== 1 ? 's' : ''} found
          </div>
          <div style={{ fontSize: '0.72rem', color: 'var(--color-text-secondary)', marginTop: '0.1rem' }}>
            ✨ Parsed by Gemini AI · {selected.size} selected for import
          </div>
        </div>
        <div style={{ display: 'flex', gap: '0.5rem' }}>
          <button onClick={() => setState('idle')} className="btn btn-outline">Back</button>
          <button onClick={handleImport} disabled={selected.size === 0} className="btn btn-primary" style={{ display: 'flex', alignItems: 'center', gap: '0.3rem' }}>
            Import {selected.size} <ChevronRight size={13} />
          </button>
        </div>
      </div>

      <div style={{ maxHeight: 320, overflowY: 'auto', borderRadius: 8, border: '1px solid var(--border)' }}>
        <table className="data-table" style={{ fontSize: '0.78rem' }}>
          <thead>
            <tr>
              <th style={{ width: 32 }}>
                <input type="checkbox"
                  checked={selected.size === parsed.length}
                  onChange={e => setSelected(e.target.checked ? new Set(parsed.map((_, i) => i)) : new Set())} />
              </th>
              <th>Description</th>
              <th>Date</th>
              <th>Category</th>
              <th style={{ textAlign: 'right' }}>Amount</th>
            </tr>
          </thead>
          <tbody>
            {parsed.map((t, i) => (
              <tr key={i} onClick={() => toggleRow(i)} style={{ cursor: 'pointer', opacity: selected.has(i) ? 1 : 0.45 }}>
                <td><input type="checkbox" checked={selected.has(i)} onChange={() => toggleRow(i)} onClick={e => e.stopPropagation()} /></td>
                <td style={{ maxWidth: 180, overflow: 'hidden', textOverflow: 'ellipsis', whiteSpace: 'nowrap' }}>{t.name}</td>
                <td>{t.date}</td>
                <td>
                  <span style={{ fontSize: '0.7rem', padding: '2px 6px', borderRadius: 4, background: 'var(--bg-hover)', color: 'var(--color-text-secondary)' }}>
                    {t.category}
                  </span>
                </td>
                <td style={{ textAlign: 'right', fontFamily: 'Space Grotesk,sans-serif', fontWeight: 700, color: t.type === 'income' ? 'var(--color-income)' : 'var(--color-text-primary)' }}>
                  {t.type === 'income' ? '+' : '−'}KES {t.amount.toLocaleString()}
                </td>
              </tr>
            ))}
          </tbody>
        </table>
      </div>
    </div>
  );

  return (
    <div>
      {state === 'error' && (
        <div style={{ marginBottom: '0.875rem', padding: '0.75rem 1rem', borderRadius: 8, background: 'var(--color-expense-light)', border: '1px solid rgba(220,38,38,0.2)', fontSize: '0.8rem', color: 'var(--color-expense)', display: 'flex', gap: '0.5rem', alignItems: 'center' }}>
          <AlertCircle size={14} /> {errMsg}
          <button onClick={() => setState('idle')} style={{ marginLeft: 'auto', background: 'none', border: 'none', cursor: 'pointer', color: 'var(--color-expense)' }}><X size={14} /></button>
        </div>
      )}

      {/* Icon + heading */}
      <div style={{ display: 'flex', flexDirection: 'column', alignItems: 'center', marginBottom: '1rem', textAlign: 'center' }}>
        <div style={{ width: 52, height: 52, borderRadius: '50%', background: 'var(--color-mpesa)', display: 'flex', alignItems: 'center', justifyContent: 'center', marginBottom: '0.75rem', boxShadow: '0 4px 16px rgba(30,132,73,0.3)' }}>
          <Smartphone size={24} color="white" />
        </div>
        <div style={{ fontWeight: 700, fontSize: '0.95rem', color: 'var(--color-text-primary)', marginBottom: '0.25rem' }}>
          Paste M-Pesa SMS Messages
        </div>
        <p style={{ fontSize: '0.75rem', color: 'var(--color-text-secondary)', maxWidth: 340 }}>
          Copy your M-Pesa confirmation SMS messages and paste them all below.
          Gemini AI will extract every transaction automatically. Phone numbers and account details are redacted before parsing.
        </p>
      </div>

      <textarea
        value={sms}
        onChange={e => setSms(e.target.value)}
        placeholder={`Paste your M-Pesa SMS messages here…\n\nExample:\n${EXAMPLE_SMS}`}
        style={{
          width: '100%', minHeight: 180, padding: '0.75rem', borderRadius: 8,
          border: '1px solid var(--border)', background: 'var(--bg-app)',
          color: 'var(--color-text-primary)', fontSize: '0.78rem', fontFamily: 'inherit',
          resize: 'vertical', outline: 'none', lineHeight: 1.6,
          boxSizing: 'border-box',
        }}
      />

      <div style={{ display: 'flex', alignItems: 'center', justifyContent: 'space-between', marginTop: '0.75rem', flexWrap: 'wrap', gap: '0.5rem' }}>
        <span style={{ fontSize: '0.7rem', color: 'var(--color-text-secondary)' }}>
          💡 Works with Send Money, Paybill, Buy Goods, Receive, Withdraw, Fuliza
        </span>
        <button
          onClick={handleParse}
          disabled={!sms.trim()}
          className="btn btn-primary"
          style={{ display: 'flex', alignItems: 'center', gap: '0.35rem' }}
        >
          <CheckCircle2 size={14} /> Parse with AI
        </button>
      </div>
    </div>
  );
}

'use client';
import { useState, useEffect } from 'react';
import { UploadCloud, Loader2, CheckCircle2, AlertCircle, ChevronRight, X, Smartphone, FileText } from 'lucide-react';
import { importTransactions } from '@/lib/actions/transactions';
import { MpesaSmsInput } from '@/components/MpesaSmsInput';
import { toMinor } from '@/lib/money';

type ParsedRow = {
  date: string; name: string; amount: number; type: string;
  category: string; categoryId: string; note?: string;
  reference?: string; importHash?: string;
  isDuplicate?: boolean; isTransfer?: boolean;
};

type UploadState = 'idle' | 'uploading' | 'reviewing' | 'importing' | 'done' | 'error';
type Tab = 'file' | 'sms';

const EMPTY_ACCOUNTS: any[] = [];

export function SmartUpload({ onDone, initialAccounts = EMPTY_ACCOUNTS }: { onDone?: () => void, initialAccounts?: any[] }) {
  const [state,     setState]    = useState<UploadState>('idle');
  const [tab,       setTab]      = useState<Tab>('file');
  const [progress,  setProgress] = useState(0);
  const [rows,      setRows]     = useState<ParsedRow[]>([]);
  const [selected,  setSelected] = useState<Set<number>>(new Set());
  const [method,    setMethod]   = useState<'ai' | 'csv'>('csv');
  const [errMsg,    setErrMsg]   = useState('');
  const [isDragging,setDragging] = useState(false);
  const [aiConsent, setAiConsent]= useState(false);
  const [accountId, setAccountId]= useState<string>(initialAccounts.length > 0 ? initialAccounts[0].id : '');

  useEffect(() => {
    if (initialAccounts.length > 0 && !accountId) {
      setAccountId(initialAccounts[0].id);
    }
  }, [initialAccounts, accountId]);

  /* -- Upload & parse --------------------------------------- */
  async function processFile(file: File) {
    setState('uploading');
    setProgress(0);

    // Animate progress while waiting for AI
    const tick = setInterval(() => setProgress(p => Math.min(p + 8, 88)), 350);

    try {
      const formData = new FormData();
      formData.append('file', file);

      const res  = await fetch('/api/upload', { method: 'POST', body: formData });
      const data = await res.json();
      clearInterval(tick);
      setProgress(100);

      if (!res.ok || !data.success) {
        setErrMsg(data.error ?? 'Upload failed.');
        setState('error');
        return;
      }

      setTimeout(() => {
        setRows(data.transactions);
        setSelected(new Set(data.transactions.map((r: any, i: number) => 
          (r.isDuplicate || r.isTransfer) ? -1 : i
        ).filter((i: number) => i !== -1)));
        setMethod(data.method);
        setState('reviewing');
      }, 400);
    } catch {
      clearInterval(tick);
      setErrMsg('Network error — please try again.');
      setState('error');
    }
  }

  /* -- Confirm import ---------------------------------------- */
  async function confirmImport() {
    setState('importing');
    const toImport = rows.filter((r, i) => selected.has(i) && !r.isTransfer);
    try {
      await importTransactions(toImport.map(r => ({
        name: r.name, baseAmountMinor: toMinor(r.amount), type: r.type,
        categoryName: r.category, date: r.date, note: r.note,
        importHash: r.importHash, reference: r.reference
      })), accountId);
      setState('done');
      setTimeout(() => { onDone?.(); }, 1500);
    } catch (e: any) {
      setErrMsg(e.message ?? 'Import failed.');
      setState('error');
    }
  }

  function toggleRow(i: number) {
    if (rows[i].isTransfer) return; // Cannot import transfers
    setSelected(s => { 
      const n = new Set(s); 
      if (n.has(i)) {
        n.delete(i);
      } else {
        n.add(i);
      }
      return n; 
    });
  }

  /* -- SMS import handler ------------------------------------ */
  async function handleSmsImport(txs: Array<{ name: string; date: string; amount: number; type: 'income' | 'expense'; category: string; fee?: number }>) {
    if (!accountId) {
      setErrMsg('Please select an account first.');
      setState('error');
      return;
    }
    setState('importing');
    try {
      const toImport = txs.map(t => ({
        name: t.name, date: t.date, amount: t.amount,
        type: t.type as 'income' | 'expense',
        category: t.category, categoryId: '', note: '',
        categoryName: t.category,
      }));
      await importTransactions(toImport.map(r => ({
        name: r.name, baseAmountMinor: toMinor(r.amount), type: r.type,
        date: r.date, categoryName: r.categoryName, note: r.note,
      })), accountId);
      setState('done');
      setTimeout(() => { onDone?.(); }, 1500);
    } catch (e: any) {
      setErrMsg(e.message ?? 'Import failed.');
      setState('error');
    }
  }

  /* -- Idle / drop zone --------------------------------------- */
  if (state === 'idle' || state === 'error') return (
    <div>
      {/* Tab bar */}
      <div style={{ display: 'flex', gap: '0', marginBottom: '1rem', border: '1px solid var(--border)', borderRadius: 10, overflow: 'hidden', background: 'var(--bg-app)' }}>
        {([
          { key: 'file', label: 'File Upload',     icon: <FileText size={13} /> },
          { key: 'sms',  label: 'M-Pesa SMS',      icon: <Smartphone size={13} /> },
        ] as const).map(t => (
          <button
            key={t.key}
            onClick={() => setTab(t.key)}
            style={{
              flex: 1, display: 'flex', alignItems: 'center', justifyContent: 'center', gap: '0.375rem',
              padding: '0.6rem 0.5rem', border: 'none', cursor: 'pointer', fontSize: '0.78rem', fontWeight: 600,
              background: tab === t.key ? 'var(--color-brand)' : 'transparent',
              color:      tab === t.key ? 'white' : 'var(--color-text-secondary)',
              transition: 'all 0.15s',
            }}
          >
            {t.icon}{t.label}
          </button>
        ))}
      </div>

      {state === 'error' && (
        <div style={{ marginBottom: '0.875rem', padding: '0.75rem 1rem', borderRadius: 8, background: 'var(--color-expense-light)', border: '1px solid rgba(220,38,38,0.2)', fontSize: '0.8rem', color: 'var(--color-expense)', display: 'flex', gap: '0.5rem', alignItems: 'center' }}>
          <AlertCircle size={14} /> {errMsg}
          <button onClick={() => setState('idle')} style={{ marginLeft: 'auto', background: 'none', border: 'none', cursor: 'pointer', color: 'var(--color-expense)' }}><X size={14} /></button>
        </div>
      )}

      {/* Account Selector */}
      <div style={{ marginBottom: '1.25rem', textAlign: 'left' }}>
        <label style={{ display: 'block', fontSize: '0.8rem', fontWeight: 600, color: 'var(--color-text-primary)', marginBottom: '0.4rem' }}>Import into Account</label>
        <select
          value={accountId}
          onChange={e => setAccountId(e.target.value)}
          className="input-field"
          style={{ width: '100%' }}
        >
          <option value="" disabled>Select an account...</option>
          {initialAccounts.map(acc => (
            <option key={acc.id} value={acc.id}>{acc.name} ({acc.currency})</option>
          ))}
        </select>
      </div>

      {/* File upload tab */}
      {tab === 'file' && (
        <div
          onDragEnter={e => { e.preventDefault(); setDragging(true); }}
          onDragLeave={e => { e.preventDefault(); setDragging(false); }}
          onDragOver={e => e.preventDefault()}
          onDrop={e => {
            e.preventDefault();
            setDragging(false);
            if (!accountId) { setErrMsg('Please select an account first.'); setState('error'); return; }
            if (!aiConsent) { setErrMsg('Please consent to AI processing before uploading.'); setState('error'); return; }
            const f = e.dataTransfer.files[0];
            if (f) processFile(f);
          }}
          onClick={() => {
            if (!accountId) { setErrMsg('Please select an account first.'); setState('error'); return; }
            if (!aiConsent) { setErrMsg('Please consent to AI processing before uploading.'); setState('error'); return; }
            document.getElementById('smart-upload-input')?.click();
          }}
          style={{
            border: `2px dashed ${isDragging ? 'var(--color-brand)' : 'var(--border)'}`,
            borderRadius: 12, padding: '2.5rem 2rem', textAlign: 'center', cursor: 'pointer',
            background: isDragging ? 'var(--color-brand-light)' : 'var(--bg-app)',
            transition: 'all 0.15s',
          }}
        >
          <input id="smart-upload-input" type="file" accept=".pdf,.csv,.xlsx,.xls,.png,.jpg,.jpeg" style={{ display: 'none' }}
            onChange={e => { const f = e.target.files?.[0]; if (f) processFile(f); }} />
          <UploadCloud size={40} color="var(--color-brand)" style={{ margin: '0 auto 0.875rem' }} />
          <div style={{ fontWeight: 700, fontSize: '0.95rem', color: 'var(--color-text-primary)', marginBottom: '0.3rem' }}>AI Smart Upload</div>
          <p style={{ fontSize: '0.78rem', color: 'var(--color-text-secondary)', marginBottom: '1rem' }}>
            Drop your bank statement here — PDF, CSV, Excel or screenshot.<br />
            Gemini AI will auto-detect and categorise every transaction.
          </p>
          <div style={{ display: 'flex', gap: '0.75rem', justifyContent: 'center', marginBottom: '1rem' }}>
            <a
              href="/Ledger360_Template.xlsx"
              download
              className="btn btn-outline"
              style={{ textDecoration: 'none' }}
              onClick={e => e.stopPropagation()}
            >
              Download Template
            </a>
            <button className="btn btn-primary" style={{ pointerEvents: 'none' }}>Browse Files</button>
          </div>

          <label style={{ display: 'flex', alignItems: 'center', gap: '0.5rem', justifyContent: 'center', fontSize: '0.75rem', color: 'var(--color-text-secondary)', cursor: 'pointer', textAlign: 'left', maxWidth: 400, margin: '0 auto' }} onClick={e => e.stopPropagation()}>
            <input type="checkbox" checked={aiConsent} onChange={e => setAiConsent(e.target.checked)} />
            <span>I consent to having my document securely parsed by Google Gemini AI. Note: PDFs and images are sent in full (no redaction). Data is NOT used to train models.</span>
          </label>
        </div>
      )}

      {/* M-Pesa SMS tab */}
      {tab === 'sms' && (
        <MpesaSmsInput onImport={handleSmsImport} />
      )}
    </div>
  );


  /* -- Uploading --------------------------------------------- */
  if (state === 'uploading') return (
    <div style={{ textAlign: 'center', padding: '2rem' }}>
      <Loader2 size={40} color="var(--color-brand)" style={{ margin: '0 auto 1rem', animation: 'spin 1s linear infinite' }} />
      <div style={{ fontWeight: 700, fontSize: '0.9rem', color: 'var(--color-text-primary)', marginBottom: '0.5rem' }}>
        AI is reading your statement…
      </div>
      <p style={{ fontSize: '0.75rem', color: 'var(--color-text-secondary)', marginBottom: '1rem' }}>Extracting and categorising transactions</p>
      <div style={{ maxWidth: 260, margin: '0 auto' }}>
        <div className="progress-track" style={{ height: 6 }}>
          <div className="progress-fill" style={{ width: `${progress}%`, background: 'var(--color-brand-grad)', boxShadow: '0 0 10px rgba(0,112,243,0.45)', transition: 'width 0.35s ease' }} />
        </div>
        <div style={{ marginTop: '0.35rem', fontSize: '0.7rem', color: 'var(--color-text-secondary)', textAlign: 'right' }}>{progress}%</div>
      </div>
    </div>
  );

  /* -- Review ------------------------------------------------ */
  if (state === 'reviewing') return (
    <div>
      <div style={{ display: 'flex', alignItems: 'center', justifyContent: 'space-between', marginBottom: '0.875rem', flexWrap: 'wrap', gap: '0.5rem' }}>
        <div>
          <div style={{ fontWeight: 700, fontSize: '0.9rem', color: 'var(--color-text-primary)' }}>
            {rows.length} transactions found
          </div>
          <div style={{ fontSize: '0.72rem', color: 'var(--color-text-secondary)', marginTop: '0.1rem' }}>
            {method === 'ai' ? '✨ Parsed by GPT-4o Vision' : '📄 Parsed from CSV'}
            {' · '}{selected.size} selected for import
          </div>
        </div>
        <div style={{ display: 'flex', gap: '0.5rem' }}>
          <button onClick={() => setState('idle')} className="btn btn-outline">Cancel</button>
          <button onClick={confirmImport} disabled={selected.size === 0} className="btn btn-primary">
            Import {selected.size} transactions <ChevronRight size={13} />
          </button>
        </div>
      </div>

      <div style={{ maxHeight: 340, overflowY: 'auto', borderRadius: 8, border: '1px solid var(--border)' }}>
        <table className="data-table" style={{ fontSize: '0.78rem' }}>
          <thead>
            <tr>
              <th style={{ width: 32 }}>
                <input type="checkbox" checked={selected.size === rows.length}
                  onChange={e => setSelected(e.target.checked ? new Set(rows.map((_, i) => i)) : new Set())} />
              </th>
              <th>Description</th>
              <th>Date</th>
              <th>Category</th>
              <th style={{ textAlign: 'right' }}>Amount</th>
            </tr>
          </thead>
          <tbody>
            {rows.map((r, i) => {
              const rowStyle = r.isTransfer 
                ? { opacity: 0.5, background: 'var(--surface-card-hover)', cursor: 'not-allowed' }
                : { cursor: 'pointer', opacity: selected.has(i) ? 1 : 0.5, background: r.isDuplicate ? 'var(--color-expense-light)' : 'transparent' };
              
              return (
                <tr key={i} onClick={() => toggleRow(i)} style={rowStyle}>
                  <td>
                    <input type="checkbox" checked={selected.has(i)} disabled={r.isTransfer} onChange={() => toggleRow(i)} onClick={e => e.stopPropagation()} />
                  </td>
                  <td style={{ maxWidth: 200, overflow: 'hidden', textOverflow: 'ellipsis', whiteSpace: 'nowrap' }}>
                    <div style={{ fontWeight: 600 }}>{r.name}</div>
                    {r.reference && <div style={{ fontSize: '0.65rem', color: 'var(--color-text-secondary)' }}>Ref: {r.reference}</div>}
                    {r.isDuplicate && <div style={{ fontSize: '0.65rem', color: 'var(--color-expense)', fontWeight: 600 }}>Duplicate Warning</div>}
                    {r.isTransfer && <div style={{ fontSize: '0.65rem', color: 'var(--color-text-primary)', fontWeight: 600 }}>Suggested Transfer (Skipped)</div>}
                  </td>
                  <td>{r.date}</td>
                  <td>
                    <input
                      type="text"
                      value={r.category}
                      disabled={r.isTransfer}
                      onChange={(e) => {
                        const newRows = [...rows];
                        newRows[i].category = e.target.value;
                        setRows(newRows);
                      }}
                      style={{
                        background: 'transparent', border: '1px solid var(--border)', borderRadius: 4,
                        padding: '2px 6px', fontSize: '0.72rem', width: 110, color: 'var(--color-text-primary)'
                      }}
                    />
                  </td>
                  <td style={{ textAlign: 'right', fontFamily: 'Space Grotesk,sans-serif', fontWeight: 700, color: r.type === 'income' ? 'var(--color-income)' : (r.isTransfer ? 'var(--color-brand)' : 'var(--color-text-primary)') }}>
                    {r.type === 'income' ? '+' : '-'}KES {r.amount.toLocaleString()}
                  </td>
                </tr>
              );
            })}
          </tbody>
        </table>
      </div>
    </div>
  );

  /* -- Importing --------------------------------------------- */
  if (state === 'importing') return (
    <div style={{ textAlign: 'center', padding: '2rem' }}>
      <Loader2 size={32} color="var(--color-brand)" style={{ margin: '0 auto 0.875rem', animation: 'spin 1s linear infinite' }} />
      <div style={{ fontWeight: 600, color: 'var(--color-text-primary)' }}>Saving to your account…</div>
    </div>
  );

  /* -- Done --------------------------------------------------- */
  return (
    <div style={{ textAlign: 'center', padding: '2rem' }}>
      <CheckCircle2 size={40} color="var(--color-income)" style={{ margin: '0 auto 0.875rem' }} />
      <div style={{ fontWeight: 700, fontSize: '0.95rem', color: 'var(--color-income)', marginBottom: '0.3rem' }}>Import complete!</div>
      <p style={{ fontSize: '0.78rem', color: 'var(--color-text-secondary)' }}>Your transactions have been saved.</p>
    </div>
  );
}

'use server';

import { prisma } from '@/lib/prisma';
import { requireAuth } from '@/lib/actions/_auth';
import { z } from 'zod';
import { Account, Prisma } from '@prisma/client';
import { revalidatePath } from 'next/cache';

import { AccountType } from '@prisma/client';

const AccountSchema = z.object({
  name: z.string().min(1).max(100),
  type: z.nativeEnum(AccountType),
  openingMinor: z.number().int().default(0),
  archived: z.boolean().optional(),
});

const DeleteSchema = z.object({
  id: z.string().cuid(),
});

export type AccountWithBalance = Account & { balanceMinor: number };

function invalidateAccountPaths() {
  revalidatePath('/accounts');
  revalidatePath('/');
  revalidatePath('/net-worth');
}

import { BalanceService } from '../domain/services/BalanceService';
import { mapAccountToDTO, AccountDTO } from '../mappers/accounts';
import { ActionResult } from '../types/action-result';

export async function getAccounts(): Promise<ActionResult<AccountDTO[]>> {
  try {
    const user = await requireAuth();
    const enrichedAccounts = await BalanceService.getEnrichedAccounts(user.id);
    
    const dtos = enrichedAccounts
      .filter(a => !a.archived)
      .map(mapAccountToDTO);

    return { success: true, data: dtos };
  } catch (error) {
    console.error('[getAccounts] Error:', error);
    return { success: false, code: 'UNKNOWN', message: 'Failed to retrieve accounts' };
  }
}

export async function getAccountBalances(userId: string): Promise<ActionResult<AccountDTO[]>> {
  try {
    const enrichedAccounts = await BalanceService.getEnrichedAccounts(userId);
    const dtos = enrichedAccounts.map(mapAccountToDTO);
    return { success: true, data: dtos };
  } catch (error) {
    console.error('[getAccountBalances] Error:', error);
    return { success: false, code: 'UNKNOWN', message: 'Failed to compute balances' };
  }
}

export async function createAccount(rawData: unknown): Promise<ActionResult<AccountDTO>> {
  'use server';
  try {
    const user = await requireAuth();
    const parsed = AccountSchema.safeParse(rawData);
    if (!parsed.success) return { success: false, code: 'VALIDATION_ERROR', message: 'Invalid input' };
    const valid = parsed.data;

    const result = await prisma.$transaction(async (tx: Prisma.TransactionClient) => {
      const { createAccountRecord } = await import('../repositories/accounts');
      const account = await createAccountRecord(tx, {
        ...valid,
        currency: user.currency || 'KES',
        userId: user.id,
      });

      await tx.auditLog.create({
        data: {
          userId: user.id,
          action: 'CREATE_ACCOUNT',
          resource: 'Account',
          metadata: JSON.stringify({ accountId: account.id, name: account.name }),
        },
      });

      return account;
    });

    invalidateAccountPaths();
    
    const { Money } = await import('../domain/money/Money');
    const { MoneyFormatter } = await import('../domain/money/MoneyFormatter');
    
    // We mock the balance as 0 (or openingMinor) for a newly created account
    const initialMoney = Money.fromMinor(result.openingMinor, result.currency);
    const enrichedAccount = {
      ...result,
      openingMinor: Number(result.openingMinor),
      balanceMinor: initialMoney.minorUnits,
      displayBalance: MoneyFormatter.format(initialMoney),
      isOverdrawn: initialMoney.isNegative(),
      availableBalanceMinor: initialMoney.minorUnits
    };
    
    return { success: true, data: mapAccountToDTO(enrichedAccount as any) };
  } catch (error) {
    console.error('[createAccount]', error);
    return { success: false, code: 'UNKNOWN', message: 'An unexpected error occurred.' };
  }
}

export async function updateAccount(id: string, rawData: unknown): Promise<ActionResult<AccountDTO>> {
  'use server';
  try {
    const user = await requireAuth();
    const parsedId = DeleteSchema.safeParse({ id });
    if (!parsedId.success) return { success: false, code: 'VALIDATION_ERROR', message: 'Invalid ID' };
    const validId = parsedId.data.id;

    const parsedData = AccountSchema.partial().safeParse(rawData);
    if (!parsedData.success) return { success: false, code: 'VALIDATION_ERROR', message: 'Invalid input' };
    const data = parsedData.data;

    const result = await prisma.$transaction(async (tx: Prisma.TransactionClient) => {
      const { updateAccountRecord } = await import('../repositories/accounts');
      const updated = await updateAccountRecord(tx, validId, user.id, data);

      await tx.auditLog.create({
        data: {
          userId: user.id,
          action: 'UPDATE_ACCOUNT',
          resource: 'Account',
          metadata: JSON.stringify({ accountId: validId, updates: data }),
        },
      });

      return updated;
    });

    invalidateAccountPaths();
    
    const { Money } = await import('../domain/money/Money');
    const { MoneyFormatter } = await import('../domain/money/MoneyFormatter');

    const initialMoney = Money.fromMinor(result.openingMinor, result.currency);
    const enrichedAccount = {
      ...result,
      openingMinor: Number(result.openingMinor),
      balanceMinor: initialMoney.minorUnits, // Should ideally re-aggregate
      displayBalance: MoneyFormatter.format(initialMoney),
      isOverdrawn: initialMoney.isNegative(),
      availableBalanceMinor: initialMoney.minorUnits
    };
    
    return { success: true, data: mapAccountToDTO(enrichedAccount as any) };
  } catch (error: any) {
    console.error('[updateAccount]', error);
    if (error.message === 'Account not found') {
      return { success: false, code: 'NOT_FOUND', message: 'Account not found or unauthorized' };
    }
    return { success: false, code: 'UNKNOWN', message: 'An unexpected error occurred.' };
  }
}

export async function deleteAccount(id: string): Promise<ActionResult<void>> {
  'use server';
  try {
    const user = await requireAuth();
    const parsedId = DeleteSchema.safeParse({ id });
    if (!parsedId.success) return { success: false, code: 'VALIDATION_ERROR', message: 'Invalid ID' };
    const validId = parsedId.data.id;

    // Block deletion if transactions or transfers exist
    const [txCount, transferFromCount, transferToCount] = await Promise.all([
      prisma.transaction.count({ where: { accountId: validId, userId: user.id } }),
      prisma.transfer.count({ where: { fromAccountId: validId, userId: user.id } }),
      prisma.transfer.count({ where: { toAccountId: validId, userId: user.id } })
    ]);
    
    if (txCount > 0 || transferFromCount > 0 || transferToCount > 0) {
      return { success: false, code: 'CONFLICT', message: 'Cannot delete account with existing transactions or transfers. Please reassign them first.' };
    }

    await prisma.$transaction(async (tx: Prisma.TransactionClient) => {
      const { deleteAccountRecord } = await import('../repositories/accounts');
      await deleteAccountRecord(tx, validId, user.id);

      await tx.auditLog.create({
        data: {
          userId: user.id,
          action: 'DELETE_ACCOUNT',
          resource: 'Account',
          metadata: JSON.stringify({ accountId: validId }),
        },
      });
    });

    invalidateAccountPaths();
    return { success: true, data: undefined };
  } catch (error) {
    console.error('[deleteAccount]', error);
    return { success: false, code: 'UNKNOWN', message: 'An unexpected error occurred.' };
  }
}

'use server';

// src/lib/actions/budgets.ts
import { prisma } from '@/lib/prisma';

import { revalidatePath } from 'next/cache';
import { requireAuth } from './_auth';
import { z } from 'zod';



const DeleteSchema = z.object({ id: z.string().cuid() });
const EditBudgetSchema = z.object({
  name: z.string().optional(),
  limitAmountMinor: z.number().int().positive().optional(),
  period: z.enum(['weekly', 'monthly', 'yearly']).optional(),
  categoryId: z.string().cuid().optional(),
  rollover: z.boolean().optional(),
});



/* -- Add (Zod-validated) ------------------------------------ */
export async function addBudget(raw: unknown) {
  'use server';
  try {
    const { AddBudgetSchema } = await import('@/lib/validation');
    const parsed = AddBudgetSchema.safeParse(raw);
    if (!parsed.success) return { error: 'Invalid input' };
    const data = parsed.data;
    const user = await requireAuth();

    const cat = await prisma.category.findFirst({
      where: { id: data.categoryId, userId: user.id },
    });
    if (!cat) return { error: 'Invalid category' };

    await prisma.budget.create({ data: { ...data, rollover: (data as any).rollover ?? false, userId: user.id, limitAmountMinor: BigInt(data.limitAmountMinor) } });
    revalidatePath('/budgets');
    revalidatePath('/');
    return { success: true };
  } catch (error) {
    console.error('[addBudget]', error);
    return { error: 'An unexpected error occurred. Please try again.' };
  }
}

export async function deleteBudget(id: string) {
  'use server';
  const user = await requireAuth();
  try {
    const parsedId = DeleteSchema.safeParse({ id });
    if (!parsedId.success) return { error: 'Invalid input' };
    const validId = parsedId.data.id;

    await prisma.budget.deleteMany({ where: { id: validId, userId: user.id } });
    revalidatePath('/budgets');
    revalidatePath('/');
    return { success: true };
  } catch (error) {
    console.error('[deleteBudget]', error);
    return { error: 'An unexpected error occurred. Please try again.' };
  }
}

export async function editBudget(id: string, rawData: unknown) {
  'use server';
  const user = await requireAuth();
  try {
    const parsedId = DeleteSchema.safeParse({ id });
    const parsedData = EditBudgetSchema.safeParse(rawData);
    if (!parsedId.success || !parsedData.success) return { error: 'Invalid input' };
    const validId = parsedId.data.id;
    const data = parsedData.data;

    if (data.categoryId) {
      const cat = await prisma.category.findFirst({ where: { id: data.categoryId, userId: user.id } });
      if (!cat) return { error: 'Invalid category' };
    }
    const { count } = await prisma.budget.updateMany({
      where: { id: validId, userId: user.id },
      data: { ...data, limitAmountMinor: data.limitAmountMinor !== undefined ? BigInt(data.limitAmountMinor) : undefined, rollover: data.rollover },
    });
    if (count === 0) return { error: 'Budget not found or ownership failed' };
    revalidatePath('/budgets');
    revalidatePath('/');
    return { success: true };
  } catch (error) {
    console.error('[editBudget]', error);
    return { error: 'An unexpected error occurred. Please try again.' };
  }
}

'use server';

// src/lib/actions/savings.ts
// Save-More-Tomorrow commitment device (B-5, WO-15).
// Manages SavingsPlan CRUD, lazy rate escalation, and auto-save trigger.
// Every auto-save is a Transfer with source='SAVE_MORE_TOMORROW' —
// transparent and reversible (B-0). In-app modelling only.
import { prisma } from '@/lib/prisma';
import { requireAuth } from '@/lib/actions/_auth';
import { revalidatePath } from 'next/cache';

import { UpsertSavingsPlanSchema } from '@/lib/validation';
import { z } from 'zod';

/* -- Lazy escalation (no cron — B-5, design point 6) -------- */
// Advances nextEscalation in a loop until it is in the future,
// bumping currentRatePct by escalationPct each elapsed period,
// capped at maxRatePct.
function advanceEscalation(plan: {
  currentRatePct: number;
  escalationPct: number;
  maxRatePct: number;
  nextEscalation: Date;
}): { currentRatePct: number; nextEscalation: Date; changed: boolean } {
  let rate = plan.currentRatePct;
  const next = new Date(plan.nextEscalation);
  const now = new Date();
  let changed = false;

  while (next <= now) {
    rate = Math.min(rate + plan.escalationPct, plan.maxRatePct);
    next.setMonth(next.getMonth() + 1);
    changed = true;
  }

  return { currentRatePct: rate, nextEscalation: next, changed };
}

/* -- Get plan (with lazy escalation applied) ---------------- */


/* -- Upsert plan -------------------------------------------- */
export async function upsertSavingsPlan(raw: unknown) {
  'use server';
  const user = await requireAuth();
  try {
    const parsed = UpsertSavingsPlanSchema.safeParse(raw);
    if (!parsed.success) return { error: 'Invalid input' };
    const data = parsed.data;

    const [fromAccount, toAccount] = await Promise.all([
      prisma.account.findFirst({ where: { id: data.fromAccountId, userId: user.id } }),
      prisma.account.findFirst({ where: { id: data.toAccountId, userId: user.id } }),
    ]);
    if (!fromAccount) return { error: 'Please choose a valid source account.' };
    if (!toAccount) return { error: 'Please choose a valid destination account.' };

    const isSavingsAccount = ['SAVINGS', 'BROKERAGE', 'CRYPTO', 'SACCO_DEPOSIT'].includes(toAccount.type);
    if (!isSavingsAccount && !data.goalId) {
      return { error: 'The destination must be a savings or investment account, or you must select a goal.' };
    }

    if (data.goalId) {
      const goal = await prisma.goal.findFirst({ where: { id: data.goalId, userId: user.id } });
      if (!goal) return { error: 'Please choose a valid goal.' };
    }

    await prisma.$transaction(async (tx) => {
      const existing = await tx.savingsPlan.findUnique({ where: { userId: user.id } });

      if (existing) {
        const { count } = await tx.savingsPlan.updateMany({
          where: { id: existing.id, userId: user.id },
          data: {
            fromAccountId:  data.fromAccountId,
            toAccountId:    data.toAccountId,
            goalId:         data.goalId || null,
            baseRatePct:    data.baseRatePct,
            escalationPct:  data.escalationPct,
            maxRatePct:     data.maxRatePct,
            active:         data.active,
          },
        });
        if (count === 0) throw new Error('Plan not found or unauthorized');
      } else {
        const prefs = await tx.userPreferences.findUnique({ where: { userId: user.id } });
        const seedRate = prefs?.savingRate ?? data.baseRatePct;

        const nextEsc = new Date();
        nextEsc.setMonth(nextEsc.getMonth() + 1);

        await tx.savingsPlan.create({
          data: {
            userId:         user.id,
            fromAccountId:  data.fromAccountId,
            toAccountId:    data.toAccountId,
            goalId:         data.goalId || null,
            baseRatePct:    data.baseRatePct,
            escalationPct:  data.escalationPct,
            maxRatePct:     data.maxRatePct,
            currentRatePct: Math.min(seedRate, data.maxRatePct),
            nextEscalation: nextEsc,
            active:         data.active,
          },
        });
      }

      await tx.auditLog.create({
        data: {
          userId: user.id,
          action: existing ? 'UPDATE' : 'CREATE',
          resource: 'SavingsPlan',
          metadata: JSON.stringify({ active: data.active }),
        }
      });
    });

    revalidatePath('/settings');
    revalidatePath('/');
    return { success: true };
  } catch (error) {
    console.error('[upsertSavingsPlan]', error);
    return { error: 'An unexpected error occurred. Please try again.' };
  }
}

/* -- Toggle active ------------------------------------------ */
export async function toggleSavingsPlan(active: unknown) {
  'use server';
  const user = await requireAuth();
  try {
    const parsed = z.boolean().safeParse(active);
    if (!parsed.success) return { error: 'Invalid input' };

    await prisma.$transaction(async (tx) => {
      const { count } = await tx.savingsPlan.updateMany({
        where: { userId: user.id },
        data: { active: parsed.data },
      });
      if (count === 0) throw new Error('No savings plan found.');

      await tx.auditLog.create({
        data: {
          userId: user.id,
          action: 'UPDATE',
          resource: 'SavingsPlan',
          metadata: JSON.stringify({ active: parsed.data }),
        }
      });
    });

    revalidatePath('/settings');
    return { success: true };
  } catch (error) {
    console.error('[toggleSavingsPlan]', error);
    return { error: 'An unexpected error occurred. Please try again.' };
  }
}

/* -- Get recent auto-saves for UI --------------------------- */


/* -- Delete plan -------------------------------------------- */
export async function deleteSavingsPlan() {
  'use server';
  const user = await requireAuth();
  try {
    await prisma.$transaction(async (tx) => {
      const { count } = await tx.savingsPlan.deleteMany({
        where: { userId: user.id },
      });
      if (count === 0) throw new Error('No savings plan found.');

      await tx.auditLog.create({
        data: {
          userId: user.id,
          action: 'DELETE',
          resource: 'SavingsPlan',
          metadata: JSON.stringify({}),
        }
      });
    });

    revalidatePath('/settings');
    revalidatePath('/');
    return { success: true };
  } catch (error) {
    console.error('[deleteSavingsPlan]', error);
    return { error: 'An unexpected error occurred. Please try again.' };
  }
}

/* -- Auto-save trigger (called from addTransaction / importTransactions) -- */
// Design point 3: self-contained prisma.transfer.create (like loan disbursement).
// Design point 4: idempotency via unique sourceTransactionId.
// Design point 5: failure isolation — never throws; returns warning string or null.
// Design point 6: lazy escalation applied before computing amount.
// REQUIRED ADDITION: only fires when income date >= plan.createdAt.
// SAFETY: skips if source account has insufficient funds.
export async function triggerAutoSave(
  userId: string,
  incomeTransactions: { id: string; baseAmountMinor: number; date: Date }[],
  userCurrency: string,
): Promise<string | null> {
  if (!incomeTransactions.length) return null;
  try {
    // 1. Get the plan
    const plan = await prisma.savingsPlan.findUnique({
      where: { userId },
      include: {
        fromAccount: { select: { id: true, type: true, currency: true } },
      },
    });

    // Guard: no plan, or inactive
    if (!plan || !plan.active) return null;

    // Filter to valid transactions on/after plan.createdAt
    const validIncomes = incomeTransactions.filter((tx: any) => new Date(tx.date) >= plan.createdAt);
    if (validIncomes.length === 0) return null;

    // 2. Lazy escalation
    const esc = advanceEscalation(plan);
    if (esc.changed) {
      await prisma.savingsPlan.updateMany({
        where: { id: plan.id, userId },
        data: { currentRatePct: esc.currentRatePct, nextEscalation: esc.nextEscalation },
      });
    }

    const rate = esc.currentRatePct;

    // 3. Compute amounts
    const transfersToCreate: any[] = [];
    const logEntries: any[] = [];
    let totalNeeded = 0;

    for (const tx of validIncomes) {
      const autoSaveMinor = Math.round(Number(tx.baseAmountMinor) * rate / 100);
      if (autoSaveMinor > 0) {
        transfersToCreate.push({
          userId,
          fromAccountId: plan.fromAccountId,
          toAccountId: plan.toAccountId,
          amountMinor: autoSaveMinor,
          currency: plan.fromAccount?.currency || userCurrency || 'KES',
          baseAmountMinor: autoSaveMinor,
          fxRate: 1,
          date: new Date(tx.date),
          source: 'SAVE_MORE_TOMORROW',
          goalId: plan.goalId || null,
          loanId: null,
          sourceTransactionId: tx.id,
        });
        logEntries.push({
          source: 'SAVE_MORE_TOMORROW',
          amount: autoSaveMinor,
          rate,
          triggeredBy: tx.id,
        });
        totalNeeded += autoSaveMinor;
      }
    }

    if (transfersToCreate.length === 0) return null;

    // 4. Balance check
    const { getAccountBalances } = await import('@/lib/queries/accounts');
    const balances = await getAccountBalances({ userId });
    const sourceAcc = balances.find((a: any) => a.id === plan.fromAccountId);
    if (sourceAcc && sourceAcc.type !== 'CREDIT_CARD' && Number(sourceAcc.balanceMinor) < totalNeeded) {
      return `Auto-save skipped: not enough funds in ${sourceAcc.name ?? 'source account'} (available: ${sourceAcc.currency} ${(Number(sourceAcc.balanceMinor) / 100).toFixed(2)}, needed: ${(totalNeeded / 100).toFixed(2)}).`;
    }

    // 5. Create transfers in bulk, ignoring conflicts for idempotency
    await prisma.$transaction(async (tx) => {
      await tx.transfer.createMany({
        data: transfersToCreate,
        skipDuplicates: true,
      });

      for (const log of logEntries) {
        await tx.auditLog.create({
          data: {
            userId,
            action: 'CREATE',
            resource: 'Transfer',
            metadata: JSON.stringify(log),
          }
        });
      }
    });

    return null; // success, no warning
  } catch (err: unknown) {
    // Design point 4 — idempotency: unique constraint violation = already saved
    const message = err instanceof Error ? err.message : String(err);
    if (message.includes('Unique constraint') && message.includes('sourceTransactionId')) {
      // Already created — idempotent, no error
      return null;
    }

    // Design point 5 — failure isolation: log and return warning, never throw
    console.error('[SaveMoreTomorrow] Auto-save failed (non-blocking):', message);
    return `Auto-save failed: ${message}`;
  }
}

