// src/lib/auth.ts
// NextAuth configuration with security hardening:
//   - Login rate limiting (10 attempts / 15 min per IP)
//   - 7-day JWT session max-age (appropriate for a financial app)
//   - NEXTAUTH_SECRET startup validation
//   - JWT refresh on session update to pick up profile changes
import { type NextAuthOptions } from 'next-auth';
import CredentialsProvider from 'next-auth/providers/credentials';

import bcrypt from 'bcryptjs';
import * as argon2 from '@node-rs/argon2';
import { prisma } from './prisma';
import { checkLimit } from './rateLimit';

// Fail fast at startup if secret is missing — random per-process secret
// would invalidate all sessions on every deploy.
if (!process.env.NEXTAUTH_SECRET) {
  throw new Error(
    'NEXTAUTH_SECRET environment variable is not set. ' +
    'Generate one with: openssl rand -base64 32'
  );
}

export const authOptions: NextAuthOptions = {
  session: {
    strategy: 'jwt',
    // 7-day lifetime — shorter than default 30 days, appropriate for finance
    maxAge: 7 * 24 * 60 * 60,
  },
  pages: {
    signIn: '/login',
    newUser: '/signup',
  },
  providers: [
    CredentialsProvider({
      name: 'credentials',
      credentials: {
        email:    { label: 'Email',    type: 'email'    },
        password: { label: 'Password', type: 'password' },
        // We no longer rely on client-supplied IP
      },
      async authorize(credentials, req) {
        if (!credentials?.email || !credentials?.password) return null;

        // -- Rate limit by IP ----------------------------------------------
        const forwardedFor = req?.headers?.['x-forwarded-for'];
        const ip = (typeof forwardedFor === 'string' ? forwardedFor.split(',')[0].trim() : undefined) ?? 'unknown';
        const rl = await checkLimit('login', `login:${ip}`);
        if (!rl.ok) {
          // Throwing causes NextAuth to surface "CredentialsSignin" error.
          // The login form maps any error to a generic message — safe.
          throw new Error(`Too many login attempts. Try again in ${rl.retryAfter}s.`);
        }

        const user = await prisma.user.findUnique({
          where: { email: credentials.email.toLowerCase().trim() },
        });

        if (!user || !user.password) return null;

        const isBcrypt = user.password.startsWith('$2a$') || user.password.startsWith('$2b$');
        const valid = isBcrypt
          ? await bcrypt.compare(credentials.password, user.password)
          : await argon2.verify(user.password, credentials.password);
          
        if (!valid) return null;

        return {
          id:             user.id,
          email:          user.email,
          name:           user.name,
          accountType:    user.accountType,
          currency:       user.currency,
          sessionVersion: user.sessionVersion,
        };
      },
    }),
  ],
  callbacks: {
    async jwt({ token, user }) {
      if (user) {
        token.id             = (user as any).id;
        token.accountType    = (user as any).accountType;
        token.currency       = (user as any).currency;
        token.sessionVersion = (user as any).sessionVersion;
      }
      
      // Fetch fresh data from DB on every request to ensure session validity and sync currency
      if (token.id) {
        try {
          const fresh = await prisma.user.findUnique({
            where: { id: token.id as string },
            select: { accountType: true, currency: true, name: true, sessionVersion: true },
          });
          
          // If user was deleted or sessionVersion changed (e.g. password reset), invalidate token
          if (!fresh || (token.sessionVersion !== undefined && fresh.sessionVersion !== token.sessionVersion)) {
            // Return token with an error flag to invalidate session
            return { ...token, error: "SessionExpired" } as any;
          }
          
          // Auto-sync currency and profile
          if (fresh) {
            token.accountType    = fresh.accountType;
            token.currency       = fresh.currency;
            token.name           = fresh.name;
            token.sessionVersion = fresh.sessionVersion;
          }
        } catch {
          // DB error - keep stale token
        }
      }
      return token;
    },
    async session({ session, token }) {
      if ((token as any).error) {
        // Return an empty session to force logout
        return {} as any;
      }
      if (session.user) {
        session.user.id          = token.id as string;
        session.user.accountType = token.accountType as string;
        session.user.currency    = token.currency as string;
      }
      return session;
    },
  },
};

// src/lib/behavioral.ts
import { prisma } from '@/lib/prisma';
import { getLoansForUser } from './queries/loans';
import type { Budget } from '@prisma/client';

export async function safeToSpend(userId: string, period: 'weekly' | 'monthly' | 'yearly' = 'monthly'): Promise<{
  discretionaryMinor: number;
  remainingMinor: number;
  perDayMinor: number;
  daysLeft: number;
  breakdown: {
    expectedIncome: number;
    baseEnvelopeLimits: number;
    plannedSavings: number;
    loanDue: number;
    unbudgetedSpendThisPeriod: number;
    envelopeOverspendPenalty: number;
  };
}> {
  // 1. Establish period bounds
  const now = new Date();
  let from: Date, to: Date;
  
  if (period === 'monthly') {
    from = new Date(now.getFullYear(), now.getMonth(), 1);
    to = new Date(now.getFullYear(), now.getMonth() + 1, 0, 23, 59, 59, 999);
  } else if (period === 'weekly') {
    // Assuming Monday start
    const day = now.getDay() || 7; 
    from = new Date(now);
    from.setHours(0, 0, 0, 0);
    from.setDate(now.getDate() - day + 1);
    to = new Date(from);
    to.setDate(from.getDate() + 6);
    to.setHours(23, 59, 59, 999);
  } else {
    // yearly
    from = new Date(now.getFullYear(), 0, 1);
    to = new Date(now.getFullYear(), 11, 31, 23, 59, 59, 999);
  }

  const daysLeftInPeriod = Math.max(1, Math.ceil((to.getTime() - now.getTime()) / 86400000));

  // 2. Fetch User Preferences
  const prefs = await prisma.userPreferences.findUnique({ where: { userId } });
  const savingRate = prefs?.savingRate ?? 30;

  // 3. Expected Income
  let expectedIncome = 0;
  if (period === 'monthly') {
    if (prefs?.expectedMonthlyIncomeMinor != null) {
      expectedIncome = prefs.expectedMonthlyIncomeMinor;
    } else {
      // Average of income over 3 complete calendar months before current month
      const threeMonthsAgoStart = new Date(from.getFullYear(), from.getMonth() - 3, 1);
      const lastMonthEnd = new Date(from.getFullYear(), from.getMonth(), 0, 23, 59, 59, 999);
      
      const oldestIncome = await prisma.transaction.findFirst({
        where: { userId, type: 'income', date: { lte: lastMonthEnd } },
        orderBy: { date: 'asc' }
      });

      if (oldestIncome) {
        const trailingIncome = await prisma.transaction.aggregate({
          where: { userId, type: 'income', date: { gte: threeMonthsAgoStart, lte: lastMonthEnd } },
          _sum: { baseAmountMinor: true }
        });
        
        // Calculate months of history (capped at 3)
        const oldestMonth = oldestIncome.date.getFullYear() * 12 + oldestIncome.date.getMonth();
        const lastMonth = lastMonthEnd.getFullYear() * 12 + lastMonthEnd.getMonth();
        const historyMonths = Math.max(1, lastMonth - oldestMonth + 1);
        const divisor = Math.min(3, historyMonths);
        
        expectedIncome = Math.round(Number(trailingIncome._sum.baseAmountMinor ?? 0) / divisor);
      }

      // If no history (or average is 0), fall back to current period actual income
      if (expectedIncome === 0) {
        const currentIncomeRows = await prisma.transaction.aggregate({
          where: { userId, type: 'income', date: { gte: from, lte: to } },
          _sum: { baseAmountMinor: true }
        });
        expectedIncome = Number(currentIncomeRows._sum.baseAmountMinor ?? 0);
      }
    }
  } else {
    // Actual income recorded this period (fallback for weekly/yearly)
    const incomeRows = await prisma.transaction.aggregate({
      where: { userId, type: 'income', date: { gte: from, lte: to } },
      _sum: { baseAmountMinor: true }
    });
    expectedIncome = Number(incomeRows._sum.baseAmountMinor ?? 0);
  }

  // 4. Planned Savings
  const plannedSavings = Math.floor(expectedIncome * (savingRate / 100));

  // 5. Loan Due
  const loans = await getLoansForUser({ userId });
  let loanDue = 0;
  for (const l of loans) {
    if (new Date(l.nextDue) <= to) {
      loanDue += l.monthlyPaymentMinor;
    }
  }

  // 6. Envelopes (Budgets)
  const budgets: Budget[] = await prisma.budget.findMany({
    where: { userId, period },
  });
  
  const budgetedCategoryIds = new Set(budgets.map(b => b.categoryId));
  
  let baseEnvelopeLimits = 0;
  let envelopeOverspendPenalty = 0;

  // Fetch spend for all budgeted categories this period in ONE query
  const spendThisPeriodGroups = await prisma.transaction.groupBy({
    by: ['categoryId'],
    where: { userId, type: 'expense', categoryId: { in: Array.from(budgetedCategoryIds) }, date: { gte: from, lte: to } },
    _sum: { baseAmountMinor: true }
  });
  
  const spendThisPeriodMap = new Map(spendThisPeriodGroups.map((g: any) => [g.categoryId, Number(g._sum.baseAmountMinor ?? 0)]));

  // Fetch unbudgeted spend in parallel with rollover queries
  const unbudgetedPromise = prisma.transaction.aggregate({
    where: { 
      userId, 
      type: 'expense', 
      date: { gte: from, lte: to },
      categoryId: { notIn: Array.from(budgetedCategoryIds) } 
    },
    _sum: { baseAmountMinor: true }
  });

  // Calculate limits and execute rollover queries concurrently
  const rolloverBudgets = budgets.filter(b => b.rollover);
  const rolloverSpends = await Promise.all(rolloverBudgets.map(b => 
    prisma.transaction.aggregate({
      where: { userId, categoryId: b.categoryId, type: 'expense', date: { gte: b.createdAt, lte: to } },
      _sum: { baseAmountMinor: true }
    })
  ));
  
  const rolloverSpendMap = new Map(rolloverBudgets.map((b: any, i: number) => [b.id, Number(rolloverSpends[i]._sum.baseAmountMinor ?? 0)]));

  for (const b of budgets) {
    baseEnvelopeLimits += Number(b.limitAmountMinor);
    const envelopeSpend = spendThisPeriodMap.get(b.categoryId) ?? 0;
    const envelopeEffectiveLimit = Number(b.limitAmountMinor);

    if (b.rollover) {
      let periodsExisted = 1;
      if (b.createdAt < from) {
        if (period === 'monthly') {
          const m1 = b.createdAt.getFullYear() * 12 + b.createdAt.getMonth();
          const m2 = from.getFullYear() * 12 + from.getMonth();
          periodsExisted = Math.max(1, m2 - m1 + 1);
        } else if (period === 'yearly') {
          periodsExisted = Math.max(1, from.getFullYear() - b.createdAt.getFullYear() + 1);
        } else if (period === 'weekly') {
          periodsExisted = Math.max(1, Math.floor((from.getTime() - b.createdAt.getTime()) / (7 * 86400000)) + 1);
        }
      }
      
      const cumulativeLimit = Number(b.limitAmountMinor) * periodsExisted;
      const cumulativeSpend = rolloverSpendMap.get(b.id) ?? 0;
      
      envelopeOverspendPenalty += Math.max(0, cumulativeSpend - cumulativeLimit);
    } else {
      envelopeOverspendPenalty += Math.max(0, envelopeSpend - envelopeEffectiveLimit);
    }
  }

  // 7. Unbudgeted Spend
  const unbudgetedAgg = await unbudgetedPromise;
  const unbudgetedSpendThisPeriod = Number(unbudgetedAgg._sum.baseAmountMinor ?? 0);

  // 8. Final Math
  const discretionaryMinor = expectedIncome - baseEnvelopeLimits - plannedSavings - loanDue;
  const remainingMinor = discretionaryMinor - unbudgetedSpendThisPeriod - envelopeOverspendPenalty;
  const perDayMinor = Math.floor(Math.max(0, remainingMinor) / daysLeftInPeriod);

  return {
    discretionaryMinor,
    remainingMinor,
    perDayMinor,
    daysLeft: daysLeftInPeriod,
    breakdown: {
      expectedIncome,
      baseEnvelopeLimits,
      plannedSavings,
      loanDue,
      unbudgetedSpendThisPeriod,
      envelopeOverspendPenalty
    }
  };
}

import { getAccountsByUserId } from '../../repositories/accounts';
import { getTransactionSumsByAccount } from '../../repositories/transactions';
import { getTransferSumsByAccount } from '../../repositories/transfers';
import { AccountAggregator } from '../calculators/AccountAggregator';
import { MoneyFormatter } from '../money/MoneyFormatter';

export type EnrichedAccountData = {
  id: string;
  userId: string;
  name: string;
  type: string;
  currency: string;
  openingMinor: number;
  archived: boolean;
  createdAt: Date;
  chamaDetails?: any;
  
  // Computed domain fields
  balanceMinor: number;
  displayBalance: string;
  isOverdrawn: boolean;
  availableBalanceMinor: number;
};

export class BalanceService {
  /**
   * Fetches the ledger state and orchestrates the aggregation of balances for all accounts.
   */
  static async getEnrichedAccounts(userId: string): Promise<EnrichedAccountData[]> {
    // 1. Fetch persistence data
    const accounts = await getAccountsByUserId(userId);
    if (accounts.length === 0) return [];

    const { incomeSums, expenseSums } = await getTransactionSumsByAccount({ userId });
    const { transfersOut, transfersIn } = await getTransferSumsByAccount(userId);

    const incMap = new Map(incomeSums.map((g: any) => [g.accountId, Number(g._sum?.baseAmountMinor ?? 0)]));
    const expMap = new Map(expenseSums.map((g: any) => [g.accountId, Number(g._sum?.baseAmountMinor ?? 0)]));
    const txOutMap = new Map(transfersOut.map((g: any) => [g.fromAccountId, Number(g._sum?.amountMinor ?? 0)]));
    const txInMap = new Map(transfersIn.map((g: any) => [g.toAccountId, Number(g._sum?.baseAmountMinor ?? 0)]));

    // 2. Orchestrate calculations
    return accounts.map(acc => {
      const summary = {
        accountId: acc.id,
        currency: acc.currency,
        openingMinor: Number(acc.openingMinor),
        totalIncomeMinor: incMap.get(acc.id) ?? 0,
        totalExpenseMinor: expMap.get(acc.id) ?? 0,
        totalTransfersInMinor: txInMap.get(acc.id) ?? 0,
        totalTransfersOutMinor: txOutMap.get(acc.id) ?? 0,
      };

      const balanceMoney = AccountAggregator.aggregate(summary);

      // 3. Prepare enrichment fields
      return {
        ...acc,
        openingMinor: Number(acc.openingMinor),
        balanceMinor: balanceMoney.minorUnits,
        displayBalance: MoneyFormatter.format(balanceMoney),
        isOverdrawn: balanceMoney.isNegative(),
        availableBalanceMinor: balanceMoney.minorUnits, // could subtract holds/reserves here in the future
      };
    });
  }
}

import { TransactionNormalizer, RawTransaction } from '../transactions/TransactionNormalizer';
import { Money } from '../money/Money';

export class TransactionService {
  /**
   * Processes a new incoming transaction (e.g. from UI or Import).
   * It pushes it through the normalization pipeline before returning
   * the payload ready for the Repository.
   */
  static processNewTransaction(
    accountId: string,
    amount: Money,
    type: 'income' | 'expense',
    merchantName: string,
    date: Date,
    notes?: string,
    categoryHint?: string
  ) {
    const raw: RawTransaction = {
      accountId,
      amount,
      type,
      rawMerchantName: merchantName,
      date,
      notes,
      originalCategoryHint: categoryHint
    };

    const verified = TransactionNormalizer.process(raw);

    return {
      persistencePayload: {
        accountId: verified.accountId,
        baseAmountMinor: BigInt(verified.amount.minorUnits),
        currency: verified.amount.currency,
        type: verified.type,
        name: verified.rawMerchantName, // Preserve raw in DB
        note: verified.notes,
        date: verified.date,
        categoryHint: verified.classification.categoryNameHint,
        // The repository will need to resolve classification.categoryNameHint to a real categoryId
      },
      metadata: {
        normalizedMerchantName: verified.normalizedMerchantName,
        merchantConfidence: verified.classification.merchantConfidence,
        categoryConfidence: verified.classification.categoryConfidence,
        isVerified: verified.isVerified,
        categoryHint: verified.classification.categoryNameHint
      }
    };
  }

  /**
   * Enriches an existing database transaction with dynamic normalization metadata.
   */
  static enrichExistingTransaction(dbTx: any, currency: string) {
    const raw: RawTransaction = {
      accountId: dbTx.accountId,
      amount: Money.fromMinor(Number(dbTx.baseAmountMinor), currency),
      type: dbTx.type,
      rawMerchantName: dbTx.name,
      date: dbTx.date,
      notes: dbTx.note || undefined,
      originalCategoryHint: dbTx.category?.name // If we joined category
    };

    const verified = TransactionNormalizer.process(raw);

    return {
      dbTx,
      metadata: {
        normalizedMerchantName: verified.normalizedMerchantName,
        merchantConfidence: verified.classification.merchantConfidence,
        categoryConfidence: verified.classification.categoryConfidence,
        isVerified: verified.isVerified,
      }
    };
  }
}

import { v4 as uuidv4 } from 'uuid';

/**
 * Centralized logging utility for Ledger360.
 * In a real production environment, this would forward logs to Datadog, Sentry, or Logtail.
 */
class Logger {
  public server(error: unknown, context?: Record<string, any>): string {
    const errorId = `LGR-${uuidv4().substring(0, 8).toUpperCase()}`;
    const timestamp = new Date().toISOString();

    // Construct structured log
    const logPayload = {
      errorId,
      timestamp,
      level: 'ERROR',
      environment: process.env.NODE_ENV,
      message: error instanceof Error ? error.message : String(error),
      stack: error instanceof Error ? error.stack : undefined,
      context,
    };

    // In production, send `logPayload` to external logging service here.
    // For now, we emit to stdout/stderr so hosting platforms (Vercel) capture it.
    console.error(JSON.stringify(logPayload, null, 2));

    return errorId;
  }

  public client(error: unknown, context?: Record<string, any>): string {
    const errorId = `LGR-C-${uuidv4().substring(0, 8).toUpperCase()}`;
    // In production, this would send to an ingest API for client errors.
    console.error(`[Client Error ${errorId}]`, error, context);
    return errorId;
  }
}

export const logger = new Logger();

// src/lib/money.ts
// Centralised money helpers — the ONLY place minor↔major conversion happens.
// Constitution: "Convert minor<->major ONLY in src/lib/money.ts."

/**
 * Convert a major-unit value (e.g. 12.50) to minor units (1250).
 * Rounds to nearest integer to avoid floating-point drift.
 */
export function toMinor(major: number): number {
  return Math.round(major * 100);
}

/**
 * Convert minor units (1250) back to major (12.50) for display only.
 */
export function toMajor(minor: number | bigint): number {
  return Number(minor) / 100;
}

/**
 * Type-guard: assert a value is a safe integer (minor units).
 * Use at API boundaries before writing to DB.
 */
export function assertMinor(amount: any): number {
  if (typeof amount === 'bigint') return Number(amount);
  return Number(amount);
}

import { prisma } from '@/lib/prisma';

export async function getTransactionSumsByAccount({ userId }: { userId: string }) {
  const txWhere = {
    userId,
    NOT: [
      { name: { contains: 'VOIDED', mode: 'insensitive' as const } },
      { name: { contains: 'pending', mode: 'insensitive' as const } }
    ]
  };

  const [incomeSums, expenseSums] = await Promise.all([
    prisma.transaction.groupBy({
      by: ['accountId'],
      where: { ...txWhere, type: 'income' },
      _sum: { baseAmountMinor: true }
    }),
    prisma.transaction.groupBy({
      by: ['accountId'],
      where: { ...txWhere, type: 'expense' },
      _sum: { baseAmountMinor: true }
    })
  ]);

  return { incomeSums, expenseSums };
}

export async function getTransactions({ userId, accountId }: { userId: string; accountId?: string }) {
  return await prisma.transaction.findMany({
    where: { 
      userId,
      ...(accountId ? { accountId } : {})
    },
    include: { category: true },
    orderBy: { date: 'desc' }
  });
}

export async function createTransactionRecord(tx: any, data: any) {
  return await tx.transaction.create({ data });
}

export async function deleteTransactionRecord(tx: any, id: string, userId: string) {
  const { count } = await tx.transaction.deleteMany({
    where: { id, userId }
  });
  if (count === 0) throw new Error('Transaction not found or unauthorized');
}

export async function getCategoryByNameOrId({ userId, hint, type }: { userId: string; hint: string; type: string }) {
  // Check by ID first
  let cat = await prisma.category.findFirst({ where: { id: hint, userId } });
  if (cat) return cat;

  // Check by Name
  cat = await prisma.category.findFirst({ where: { name: hint, userId } });
  if (cat) return cat;

  // Create if missing
  return await prisma.category.create({
    data: { name: hint, type, userId }
  });
}
